#!/usr/bin/env python3
"""Week 6 · harness for Task 3. Do not edit this file.

Builds a random area, then replays a stream of link events - flaps, cost
changes, failures - and asks one router to keep its table right.

    area       400 routers, about 1,600 links
    events     1,000 link ups, downs and cost changes
    scored     how many full SPF runs you needed
    checked    after every event, against a full recompute

    python3 bench.py
    python3 bench.py --yours
"""
import argparse, random, time

SEED, NODES, EXTRA_LINKS, EVENTS = 246, 400, 1_200, 1_000


def build(seed=SEED):
    rng = random.Random(seed)
    names = [f"r{i:02d}" for i in range(NODES)]
    graph = {n: {} for n in names}

    def link(a, b, c):
        graph[a][b] = c
        graph[b][a] = c

    for i in range(1, NODES):                       # a spanning tree first
        link(names[i], names[rng.randrange(i)], rng.randint(1, 10))
    for _ in range(EXTRA_LINKS):                    # then some redundancy
        a, b = rng.sample(names, 2)
        if b not in graph[a]:
            link(a, b, rng.randint(1, 10))

    edges = [(a, b, c) for a in graph for b, c in graph[a].items() if a < b]
    events = []
    for _ in range(EVENTS):
        a, b, c = rng.choice(edges)
        events.append((a, b, None if rng.random() < 0.4 else rng.randint(1, 10)))
    return graph, events


def run(cls, label, graph, events, check=False):
    import task3_reconverge as T
    shadow = {n: dict(e) for n, e in graph.items()}
    source = sorted(graph)[0]

    T.SPF_RUNS = 0
    t0 = time.perf_counter()
    router = cls(graph, source)
    spf_before_checks = T.SPF_RUNS
    wrong = 0
    for a, b, cost in events:
        router.link_change(a, b, cost)
        spf_before_checks = T.SPF_RUNS
        if check:
            if cost is None:
                shadow[a].pop(b, None)
                shadow[b].pop(a, None)
            else:
                shadow[a][b] = cost
                shadow[b][a] = cost
            if router.table != T.dijkstra_table(shadow, source):
                wrong += 1
            T.SPF_RUNS = spf_before_checks      # the check itself is not your cost
    elapsed = time.perf_counter() - t0

    print(f"  {label:<14} SPF runs {T.SPF_RUNS:>5}   wall {elapsed:>6.2f}s"
          + (f"   wrong after {wrong} event(s)" if check else ""))
    return {"time": elapsed, "wrong": wrong, "spf": T.SPF_RUNS}


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    graph, events = build()
    links = sum(len(e) for e in graph.values()) // 2
    print(f"\n  {len(graph)} routers, {links} links, {len(events)} events\n")

    from task3_reconverge import FullRecompute
    base = run(FullRecompute, "baseline", graph, events)

    if a.yours:
        from task3_reconverge import YourRouter
        mine = run(YourRouter, "yours", graph, events, check=True)
        print()
        if mine["wrong"]:
            print(f"   FAIL  table was wrong after {mine['wrong']} event(s). "
                  f"Correctness first.")
        else:
            saved = 1 - mine["spf"] / base["spf"]
            print(f"   ok    table correct after every event")
            print(f"   full SPF runs avoided  {saved:.0%}  "
                  f"({mine['spf']} instead of {base['spf']})")
            grade = ("strong" if saved >= 0.75 else
                     "good" if saved >= 0.40 else
                     "pass" if saved > 0.05 else "not yet")
            print(f"\n   -> {grade}")
    print()


if __name__ == "__main__":
    main()
